package com.interview.fraud.risk;
import com.interview.fraud.transaction.TransactionEntity; import java.time.ZoneOffset; import java.util.*; import org.springframework.stereotype.Component;
@Component public class FraudRuleEngine { public Evaluation evaluate(TransactionEntity t,long history){List<Signal>s=new ArrayList<>(); if(t.amount.doubleValue()>=5000)s.add(new Signal("HIGH_AMOUNT",45,"Amount exceeds 5,000")); else if(t.amount.doubleValue()>=1000)s.add(new Signal("ELEVATED_AMOUNT",25,"Amount exceeds 1,000")); if(Set.of("CRYPTO-9","GAMBLING-7").contains(t.merchantId))s.add(new Signal("RISKY_MERCHANT",25,"Merchant profile is high risk")); int hour=t.occurredAt.atZone(ZoneOffset.UTC).getHour(); if(hour<5)s.add(new Signal("UNUSUAL_HOUR",15,"Transaction occurred 00:00-05:00 UTC")); if(!"US".equals(t.country))s.add(new Signal("CROSS_BORDER",20,"Transaction is outside customer home market")); if(history>=4)s.add(new Signal("VELOCITY",25,"Recent customer transaction count is elevated")); int score=Math.min(100,s.stream().mapToInt(Signal::weight).sum());return new Evaluation(score,s);} public record Signal(String code,int weight,String description){} public record Evaluation(int score,List<Signal> signals){} }
